" fill="#333" stroke="#fff" stroke-width="1.5" font-family="serif">♝</text></svg>', 'bN': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text x="50" y="78" font-size="80" text-anchor="middle" fill="#333" stroke="#fff" stroke-width="1.5" font-family="serif">♞</text></svg>', 'bP': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text x="50" y="78" font-size="80" text-anchor="middle" fill="#333" stroke="#fff" stroke-width="1.5" font-family="serif">♟</text></svg>'}
